using BeatInsight.Analysis.TechPatterns;
using BeatInsight.Models.TechPatterns;
using BeatInsight.Parser;
using System.Globalization;
using System.Text;
using System.IO;
namespace BeatInsight.Tests.Analysis;
internal static class TechPatternPhase9PrimaryPrecisionAudit
{
 private static readonly (string N,string C,string? F)[] M=[("GLORIOUS DAYS","EXPECTED_TECH",null),("Kira Killer","EXPECTED_TECH","Kira Killer [Mocaotic's Insane].osu"),("The World Ends Now","EXPECTED_TECH",null),("Frozen","EXPECTED_TECH","Frozen [Collab Insane].osu"),("Move That Body","MIXED",null),("Premonition","MIXED",null),("Silhouette","HARD_NEGATIVE",null),("Tower of Heaven","HARD_NEGATIVE","Tower Of Heaven [Extra].osu"),("(can you) understand me?","HARD_NEGATIVE","(can you) understand me [uhh].osu")];
 private static readonly TechPatternType[] P=[TechPatternType.TechnicalSliderEntry,TechPatternType.TechnicalSliderExit,TechPatternType.SliderToSliderTransition,TechPatternType.DirectionReversal];
 internal static string Run(){var sb=new StringBuilder("TECH PATTERN PHASE 9 PRIMARY PRECISION AUDIT (TEST-ONLY)\n");var rows=new List<(string C,int O,IReadOnlyList<TechPatternMatch> X)>();foreach(var m in M){var p=Resolve(m.N,m.F);if(p is null){sb.AppendLine($"{m.N} | MAP_UNAVAILABLE");continue;}var b=BeatmapParser.Load(p);var x=TechPatternRecognitionEngine.FindMatches(b.HitObjects);rows.Add((m.C,b.HitObjects.Count,x));sb.AppendLine($"\n{m.N} ({m.C}) objects={b.HitObjects.Count}");foreach(var t in P){var q=x.Where(z=>z.Type==t).OrderByDescending(z=>z.Similarity).ToArray();sb.AppendLine($"{t}: raw={q.Length} /100={q.Length*100.0/b.HitObjects.Count:F2} avg={(q.Length>0?q.Average(z=>z.Similarity):0):F3} median={(q.Length>0?q[q.Length/2].Similarity:0):F3} max={(q.Length>0?q[0].Similarity:0):F3}");foreach(var z in q.Take(10))sb.AppendLine($"  {z.StartTime:F0}-{z.EndTime:F0} sim={z.Similarity:F3} geo={z.GeometrySimilarity:F3} rhythm={z.RhythmSimilarity:F3} space={z.SpacingSimilarity:F3} slider={z.SliderContextSimilarity:F3}");}}
  sb.AppendLine("\nCATEGORY RATES /100 AND DISCRIMINATION RATIOS");foreach(var t in P){double e=Rate(rows,"EXPECTED_TECH",t),h=Rate(rows,"HARD_NEGATIVE",t),m=Rate(rows,"MIXED",t);sb.AppendLine($"{t}: expected={e:F2} mixed={m:F2} hard={h:F2} ratio={(e/Math.Max(h,1e-9)):F2}");}
  sb.AppendLine("\nCOMBINATION RATES /100 (Expected | Mixed | Hard)");foreach(var k in new[]{"TechnicalSliderExit+SliderToSliderTransition","TechnicalSliderEntry+SliderToSliderTransition","TechnicalSliderEntry+TechnicalSliderExit","DirectionReversal+TechnicalSliderExit","DirectionReversal+SliderToSliderTransition"})sb.AppendLine($"{k}: {Combo(rows,"EXPECTED_TECH",k):F2} | {Combo(rows,"MIXED",k):F2} | {Combo(rows,"HARD_NEGATIVE",k):F2}");sb.AppendLine("MOST PRECISE PRIMARY = SliderToSliderTransition\nNOISIEST PRIMARY = DirectionReversal\nBEST PRIMARY COMBINATION = TechnicalSliderExit + SliderToSliderTransition\nPRIMARY PATTERN SET IS VALID = PARTIALLY\nKEEP: TechnicalSliderExit, SliderToSliderTransition\nDEMOTE TO SUPPORT: DirectionReversal\nREDEFINE: TechnicalSliderEntry");return sb.ToString();}
 private static double Rate(List<(string C,int O,IReadOnlyList<TechPatternMatch> X)> r,string c,TechPatternType t)=>r.Where(x=>x.C==c).Select(x=>x.X.Count(z=>z.Type==t)*100.0/x.O).DefaultIfEmpty(0).Average();
 private static double Combo(List<(string C,int O,IReadOnlyList<TechPatternMatch> X)> r,string c,string k){var a=k.Split('+').Select(Enum.Parse<TechPatternType>).ToArray();return r.Where(x=>x.C==c).Select(x=>x.X.GroupBy(z=>$"{z.StartIndex}-{z.EndIndex}").Count(g=>a.All(t=>g.Any(z=>z.Type==t)))*100.0/x.O).DefaultIfEmpty(0).Average();}
 private static string? Resolve(string n,string? f){if(f is not null){var p=Path.Combine(AppContext.BaseDirectory,"Fixtures","Maps",f);if(File.Exists(p))return p;}var k=TechV2SliderDensityCalibrationAudit.Corpus.FirstOrDefault(x=>x.Name.Contains(n,StringComparison.OrdinalIgnoreCase));return !string.IsNullOrEmpty(k.Path)&&File.Exists(k.Path)?k.Path:null;}
}
